#!/usr/bin/env node

const http = require('http');

function makeRequest(options, data) {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: body
        });
      });
    });

    req.on('error', reject);

    if (data) {
      req.write(JSON.stringify(data));
    }

    req.end();
  });
}

async function runTests() {
  const baseOptions = {
    hostname: 'localhost',
    port: 3000,
    method: 'POST',
    path: '/check',
    headers: {
      'Content-Type': 'application/json'
    }
  };

  console.log('Testing POST /check endpoint...\n');

  // Test 1: Simple rule evaluation
  console.log('Test 1: Simple rule evaluation');
  const test1 = {
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  };

  try {
    const response1 = await makeRequest(baseOptions, test1);
    console.log('Status:', response1.statusCode);
    console.log('Response:', response1.body);
  } catch (error) {
    console.log('Error:', error.message);
  }
  console.log();

  // Test 2: Missing rule field
  console.log('Test 2: Missing rule field');
  const test2 = {
    context: { amount: 50 }
  };

  try {
    const response2 = await makeRequest(baseOptions, test2);
    console.log('Status:', response2.statusCode);
    console.log('Response:', response2.body);
  } catch (error) {
    console.log('Error:', error.message);
  }
  console.log();

  // Test 3: Health check (GET request)
  console.log('Test 3: Testing GET /health endpoint');
  const healthOptions = {
    hostname: 'localhost',
    port: 3000,
    method: 'GET',
    path: '/health'
  };

  try {
    const healthResponse = await makeRequest(healthOptions);
    console.log('Status:', healthResponse.statusCode);
    console.log('Response:', healthResponse.body);
  } catch (error) {
    console.log('Error:', error.message);
  }
}

// Check if server is running
runTests().catch(console.error);

