// Test script to verify the POST /check endpoint
const app = require('./app.js');
const request = require('supertest');

// Test cases for the rule engine
const testCases = [
  {
    name: 'Simple numeric comparison',
    rule: 'ctx.amount > 100',
    context: { amount: 150 },
    expected: true
  },
  {
    name: 'String comparison',
    rule: 'ctx.status === "approved"',
    context: { status: 'approved' },
    expected: true
  },
  {
    name: 'Complex expression with request',
    rule: 'ctx.userId === req.body.context.userId && ctx.amount < 500',
    context: { userId: 123, amount: 300 },
    expected: true
  },
  {
    name: 'False condition',
    rule: 'ctx.amount < 0',
    context: { amount: 50 },
    expected: false
  }
];

// Run tests
async function runTests() {
  console.log('Testing POST /check endpoint...\n');

  for (const testCase of testCases) {
    console.log(`Test: ${testCase.name}`);
    console.log(`Rule: ${testCase.rule}`);
    console.log(`Context: ${JSON.stringify(testCase.context)}`);

    const response = await request(app)
      .post('/check')
      .send({
        rule: testCase.rule,
        context: testCase.context
      });

    console.log(`Response status: ${response.status}`);
    console.log(`Response body: ${JSON.stringify(response.body)}`);

    if (response.status === 200 && response.body.result === testCase.expected) {
      console.log('✓ PASS\n');
    } else {
      console.log('✗ FAIL\n');
    }
  }

  // Test error cases
  console.log('Testing error cases...\n');

  // Missing rule
