    .post('/check')
    .send({ rule: 'ctx.amount > 100' });
  console.log('Missing context test:', missingContextResponse.status === 400 ? '✓ PASS' : '✗ FAIL');

  // Invalid rule expression
  const invalidRuleResponse = await request(app)
    .post('/check')
    .send({ 
      rule: 'ctx.amount >',  // Invalid syntax
      context: { amount: 100 }
    });
  console.log('Invalid rule test:', invalidRuleResponse.status === 400 ? '✓ PASS' : '✗ FAIL');

  console.log('\nAll tests completed!');
}

