// Quick test to verify the app.js logic works

// Simulate the POST /check endpoint logic
function simulateCheckEndpoint(requestBody) {
  // Mock request object
  const mockReq = {
    body: requestBody,
    ip: '127.0.0.1',
    method: 'POST'
  };

  // The evalRule function from app.js
  function evalRule(req) {
    const expr = req.body.rule;
    const ctx = { ctx: req.body.context, req };
    return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
  }

  try {
    if (!mockReq.body.rule) {
      return { status: 400, data: { error: 'Missing required field: rule' } };
    }

    if (!mockReq.body.context) {
      return { status: 400, data: { error: 'Missing required field: context' } };
    }

    const result = evalRule(mockReq);
    return { 
      status: 200, 
      data: { 
        result,
        rule: mockReq.body.rule,
        context: mockReq.body.context
      }
    };
  } catch (error) {
    return { 
      status: 400, 
      data: { 
        error: 'Failed to evaluate rule',
        message: error.message 
      }
    };
  }
}

